files.main.scss:
// Bootstrap, compiled from its Sass source. This folder is a "config": the
// same three files (main.scss, _custom.scss, tokens.css) make up every saved
// config in configs/ and every issue reproduction in issues/.
//
// Out of the box nothing is configured: the output is Bootstrap's default CSS.
// Customize at compile time by swapping the `@use` below for the `with (...)`
// version. Only list what you change; Bootstrap merges it over its defaults.
// See https://getbootstrap.com/docs/6.0/customize/sass/

@use "bootstrap/scss/bootstrap";

// @use "bootstrap/scss/bootstrap" with (
//   // Options (scss/_config.scss)
//   $enable-shadows: false,
//   $enable-gradients: false,
//   $color-mode-type: "data",
//
//   // Global tokens, output on :root (scss/_root.scss)
//   $root-tokens: (
//     --border-radius: .25rem,
//   ),
//
//   // Theme colors (scss/_theme.scss). Pass a whole sub-map per theme.
//   $theme-colors: (
//     "brand": (
//       "base": var(--indigo-500),
//       "fg": light-dark(var(--indigo-600), var(--indigo-400)),
//       "fg-emphasis": light-dark(var(--indigo-800), var(--indigo-300)),
//       "bg": var(--indigo-500),
//       "bg-subtle": light-dark(var(--indigo-100), var(--indigo-900)),
//       "bg-muted": light-dark(var(--indigo-200), var(--indigo-800)),
//       "border": light-dark(var(--indigo-300), var(--indigo-600)),
//       "focus-ring": light-dark(color-mix(in oklch, var(--indigo-500) 50%, var(--bg-body)), color-mix(in oklch, var(--indigo-500) 75%, var(--bg-body))),
//       "contrast": var(--white)
//     )
//   ),
//
//   // Component tokens, output on the component class (e.g. scss/_alert.scss)
//   $alert-tokens: (
//     --alert-padding-x: 2rem,
//   ),
// );

// Your own Sass, with access to Bootstrap's mixins and functions.
@use "custom";

files._custom.scss:
// The `@layer custom` half of the layers page. Every override uses `:where()`,
// so its specificity is 0: it can only win through layer order, never through
// a more specific selector. See index.html for what each one should do.

@layer custom {
  // Documented to lose: global tokens must stay unlayered (Bootstrap's `:root`
  // tokens are unlayered, and unlayered beats every layer).
  :root {
    --heading-margin-bottom: 7.7rem;
  }

  // Component token: `custom` comes after `components`, so it wins.
  :where(.pg-btn) {
    --btn-padding-x: 37px;
  }

  // Component rule: same.
  :where(.pg-card) {
    background-color: rgb(1, 2, 3);
  }

  // Loses to a utility (`utilities` comes after `custom`)…
  :where(.pg-util) {
    padding: 13px;
  }

  // …and to a helper (`helpers` comes after `custom`).
  :where(.pg-helper) {
    display: block;
  }

  // Should win like any component token, but the drawer's tokens are unlayered (#148).
  :where(.pg-drawer) {
    --drawer-width: 321px;
  }
}

files.tokens.css:
/*
 * The unlayered half of the layers page. Global tokens stay unlayered, and
 * this file loads after Bootstrap, so an override here wins over Bootstrap's
 * own `:root` tokens.
 */
:root {
  /* `none`: a sentinel the production build's minifier leaves as is. */
  --gradient: none;
}

files.postcss.config.js:
// Mirrors Bootstrap's own `build/postcss.config.mjs` so the CSS compiled here
// matches `dist/css/bootstrap.css`: every custom property gets the `--bs-`
// prefix (Bootstrap's JavaScript reads the prefixed names), then Autoprefixer
// runs against the targets in `.browserslistrc` (copied from Bootstrap).
import postcssPrefixCustomProperties from 'postcss-prefix-custom-properties'
import autoprefixer from 'autoprefixer'

export const DEFAULT_PREFIX = 'bs-'

// A stylesheet picks another prefix with a loud comment, which Sass keeps:
// `/*! playground-prefix: "x-" */`, or `""` for none, like the docs' npm and
// webpack guides, which run Autoprefixer only. The comment is removed.
const PREFIX_MARKER = /^!?\s*playground-prefix:\s*"([^"]*)"\s*$/

// The prefix a stylesheet asks for, or undefined.
export const readPrefix = source => source.match(/\/\*!?\s*playground-prefix:\s*"([^"]*)"\s*\*\//)?.[1]

const escapeRegExp = text => text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')

const prefixCustomProperties = {
  postcssPlugin: 'playground-prefix-custom-properties',
  Once(root) {
    let prefix = DEFAULT_PREFIX
    root.walkComments(comment => {
      const match = comment.text.match(PREFIX_MARKER)
      if (match) {
        prefix = match[1]
        comment.remove()
      }
    })

    if (prefix) {
      postcssPrefixCustomProperties({
        prefix,
        ignore: [new RegExp(`^--${escapeRegExp(prefix)}`), /^--bd-/]
      }).Once(root)
    }
  }
}

export default {
  plugins: [
    prefixCustomProperties,
    autoprefixer({ cascade: false })
  ]
}

files.vite.config.js:
import { defineConfig } from 'vite'

// Same floors as Bootstrap's `.browserslistrc`. Lower targets make the
// minifier rewrite `light-dark()`, which breaks `data-bs-theme`.
const cssTarget = ['chrome130', 'edge130', 'firefox132', 'safari18']

export default defineConfig({
  build: { target: cssTarget, cssTarget }
})
